import React, { useEffect, useMemo, useState } from "react";
import * as pdfjsLib from "pdfjs-dist";

const FOOD_BANK = [
  "אורז",
  "עוף",
  "בננה",
  "תפוח אדמה",
  "תפוחי אדמה",
  "ביצה",
  "ביצים",
  "גזר",
  "דלעת",
  "קישוא",
  "טוסט",
  "לחם לבן",
  "פסטה",
  "אטריות",
  "דג",
  "הודו",
  "יוגורט",
  "גבינה",
  "גבינות",
  "חלב",
  "תפוח",
  "אגס",
  "אבוקדו",
  "קרקר",
  "קרקרים",
  "לחם",
  "מרק",
  "שיבולת שועל",
  "טחינה",
  "מלפפון",
  "עגבניה",
  "עגבניות",
  "קטניות",
  "שעועית",
  "חומוס",
  "עדשים",
  "מטוגן",
  "מטוגנים",
  "חריף",
  "חריפים",
  "מוצרי חלב",
  "סיבים",
  "ירקות חיים",
  "סלט",
  "לחם מלא",
  "ברוקולי",
  "כרובית",
  "תירס",
  "שמן",
  "קפה",
  "תה",
  "שוקולד",
  "ממתקים",
  "פירות",
  "ירקות",
  "עוף טחון",
  "אורז לבן",
  "דייסה",
  "טונה",
  "סלמון",
  "פירה",
  "קרם אורז",
  "בשר",
  "בקר",
];

const RECIPES = [
  {
    name: "אורז עם עוף",
    ingredients: ["אורז", "עוף"],
    description: "מנה פשוטה ובסיסית.",
  },
  {
    name: "פירה עם ביצה",
    ingredients: ["תפוח אדמה", "ביצה"],
    description: "מנה רכה ונוחה יחסית לעיכול.",
  },
  {
    name: "אורז עם גזר",
    ingredients: ["אורז", "גזר"],
    description: "שילוב פשוט ועדין.",
  },
  {
    name: "מרק ירקות עדין",
    ingredients: ["גזר", "קישוא", "מרק"],
    description: "ארוחה חמה ופשוטה.",
  },
  {
    name: "חביתה עם לחם לבן",
    ingredients: ["ביצה", "לחם לבן"],
    description: "ארוחה מהירה ונגישה.",
  },
  {
    name: "בננה עם טוסט",
    ingredients: ["בננה", "טוסט"],
    description: "פתרון קל ומהיר.",
  },
  {
    name: "דג עם תפוח אדמה",
    ingredients: ["דג", "תפוח אדמה"],
    description: "מנה פשוטה עם חלבון ופחמימה.",
  },
  {
    name: "אטריות עם עוף",
    ingredients: ["אטריות", "עוף"],
    description: "מנה בסיסית ליום רגוע.",
  },
];

const emptyRegister = {
  username: "",
  password: "",
  fullName: "",
  age: "",
  diseaseType: "קרוהן",
  currentStatus: "רמיסיה",
  nutritionFileName: "",
  nutritionRawText: "",
  allowedFoods: [],
  forbiddenFoods: [],
};

function App() {
  const [screen, setScreen] = useState("auth");
  const [authMode, setAuthMode] = useState("login");

  const [loginData, setLoginData] = useState({
    username: "",
    password: "",
  });

  const [registerData, setRegisterData] = useState(emptyRegister);
  const [currentUser, setCurrentUser] = useState(null);
  const [authError, setAuthError] = useState("");

  const [pdfLoading, setPdfLoading] = useState(false);
  const [pdfMessage, setPdfMessage] = useState("");

  const [candidateAllowed, setCandidateAllowed] = useState([]);
  const [candidateForbidden, setCandidateForbidden] = useState([]);
  const [manualAllowed, setManualAllowed] = useState("");
  const [manualForbidden, setManualForbidden] = useState("");

  const [meals, setMeals] = useState([]);
  const [mealInput, setMealInput] = useState("");
  const [mealFeeling, setMealFeeling] = useState("");

  useEffect(() => {
    const savedUsername = localStorage.getItem("currentUser");
    if (!savedUsername) return;

    const users = getUsers();
    const foundUser = users.find((u) => u.username === savedUsername);

    if (foundUser) {
      setCurrentUser(foundUser);
      setMeals(loadUserMeals(foundUser.username));
      setScreen("home");
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem(`meals_${currentUser.username}`, JSON.stringify(meals));
    }
  }, [meals, currentUser]);

  const getUsers = () => {
    const raw = localStorage.getItem("users");
    return raw ? JSON.parse(raw) : [];
  };

  const saveUsers = (users) => {
    localStorage.setItem("users", JSON.stringify(users));
  };

  const loadUserMeals = (username) => {
    const raw = localStorage.getItem(`meals_${username}`);
    return raw ? JSON.parse(raw) : [];
  };

  const normalizeText = (text) => {
    return text
      .replace(/\u200f/g, "")
      .replace(/\u200e/g, "")
      .replace(/[()״"'`]/g, " ")
      .replace(/[.:;]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  };

  const uniqueArray = (arr) => [...new Set(arr.filter(Boolean))];

  const extractTextFromPdf = async (file) => {
    const arrayBuffer = await file.arrayBuffer();

    const pdf = await pdfjsLib.getDocument({
      data: arrayBuffer,
      disableWorker: true,
    }).promise;

    let fullText = "";

    for (let pageNum = 1; pageNum <= pdf.numPages; pageNum += 1) {
      const page = await pdf.getPage(pageNum);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item) => item.str).join(" ");
      fullText += pageText + "\n";
    }

    return fullText;
  };

  const extractFoodsFromRelevantLines = (text) => {
    const lines = text
      .split("\n")
      .map((line) => normalizeText(line))
      .filter(Boolean);

    const allowedKeywords = ["מותר", "מומלץ", "אפשר", "ניתן"];
    const forbiddenKeywords = ["אסור", "להימנע", "לא מומלץ", "לא כדאי"];

    const allowed = [];
    const forbidden = [];

    lines.forEach((line) => {
      const hasAllowedKeyword = allowedKeywords.some((k) => line.includes(k));
      const hasForbiddenKeyword = forbiddenKeywords.some((k) => line.includes(k));

      if (!hasAllowedKeyword && !hasForbiddenKeyword) return;

      FOOD_BANK.forEach((food) => {
        if (line.includes(food)) {
          if (hasForbiddenKeyword) {
            forbidden.push(food);
          } else if (hasAllowedKeyword) {
            allowed.push(food);
          }
        }
      });
    });

    return {
      allowed: uniqueArray(allowed),
      forbidden: uniqueArray(forbidden),
    };
  };

  const handlePdfUpload = async (file) => {
    if (!file) return;

    setPdfLoading(true);
    setPdfMessage("קורא את ה־PDF...");

    try {
      const extractedText = await extractTextFromPdf(file);
      const detected = extractFoodsFromRelevantLines(extractedText);

      setRegisterData((prev) => ({
        ...prev,
        nutritionFileName: file.name,
        nutritionRawText: extractedText,
      }));

      setCandidateAllowed(detected.allowed);
      setCandidateForbidden(detected.forbidden);

      setPdfMessage(
        "הקובץ נסרק. מוצגים רק מאכלים שנמצאו בשורות שקשורות למותר/אסור."
      );
      setScreen("reviewFoods");
    } catch (error) {
      console.error(error);
      setPdfMessage("לא הצלחתי לקרוא את ה־PDF. נסה PDF עם טקסט ברור.");
    } finally {
      setPdfLoading(false);
    }
  };

  const registerUser = () => {
    setAuthError("");

    if (
      !registerData.fullName.trim() ||
      !registerData.username.trim() ||
      !registerData.password.trim()
    ) {
      setAuthError("יש למלא שם מלא, שם משתמש וסיסמה");
      return;
    }

    const users = getUsers();
    const exists = users.find((u) => u.username === registerData.username.trim());

    if (exists) {
      setAuthError("שם המשתמש כבר קיים");
      return;
    }

    const newUser = {
      ...registerData,
      username: registerData.username.trim(),
      password: registerData.password.trim(),
      fullName: registerData.fullName.trim(),
      allowedFoods: uniqueArray(candidateAllowed),
      forbiddenFoods: uniqueArray(candidateForbidden),
    };

    saveUsers([...users, newUser]);
    localStorage.setItem("currentUser", newUser.username);

    setCurrentUser(newUser);
    setMeals([]);
    setScreen("home");
    setRegisterData(emptyRegister);
    setCandidateAllowed([]);
    setCandidateForbidden([]);
    setManualAllowed("");
    setManualForbidden("");
    setPdfMessage("");
  };

  const loginUser = () => {
    setAuthError("");

    if (!loginData.username.trim() || !loginData.password.trim()) {
      setAuthError("יש למלא שם משתמש וסיסמה");
      return;
    }

    const users = getUsers();
    const foundUser = users.find(
      (u) =>
        u.username === loginData.username.trim() &&
        u.password === loginData.password.trim()
    );

    if (!foundUser) {
      setAuthError("שם משתמש או סיסמה לא נכונים");
      return;
    }

    localStorage.setItem("currentUser", foundUser.username);
    setCurrentUser(foundUser);
    setMeals(loadUserMeals(foundUser.username));
    setScreen("home");
    setLoginData({ username: "", password: "" });
  };

  const logoutUser = () => {
    localStorage.removeItem("currentUser");
    setCurrentUser(null);
    setMeals([]);
    setMealInput("");
    setMealFeeling("");
    setScreen("auth");
  };

  const saveProfileChanges = () => {
    if (!currentUser) return;

    const users = getUsers();
    const updatedUsers = users.map((u) =>
      u.username === currentUser.username ? currentUser : u
    );

    saveUsers(updatedUsers);
    setScreen("home");
  };

  const saveMeal = () => {
    if (!mealInput.trim() || !mealFeeling) return;

    const nextMeals = [
      ...meals,
      { name: mealInput.trim(), feeling: mealFeeling },
    ];

    setMeals(nextMeals);
    setMealInput("");
    setMealFeeling("");
    setScreen("home");
  };

  const deleteMeal = (indexToDelete) => {
    setMeals(meals.filter((_, index) => index !== indexToDelete));
  };

  const removeAllowed = (food) => {
    setCandidateAllowed(candidateAllowed.filter((item) => item !== food));
  };

  const removeForbidden = (food) => {
    setCandidateForbidden(candidateForbidden.filter((item) => item !== food));
  };

  const addManualAllowed = () => {
    if (!manualAllowed.trim()) return;
    setCandidateAllowed(uniqueArray([...candidateAllowed, manualAllowed.trim()]));
    setManualAllowed("");
  };

  const addManualForbidden = () => {
    if (!manualForbidden.trim()) return;
    setCandidateForbidden(
      uniqueArray([...candidateForbidden, manualForbidden.trim()])
    );
    setManualForbidden("");
  };

  const updateCurrentUserField = (field, value) => {
    setCurrentUser((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const suggestedRecipes = useMemo(() => {
    if (!currentUser) return [];

    const allowed = currentUser.allowedFoods || [];
    const forbidden = currentUser.forbiddenFoods || [];

    return RECIPES.filter((recipe) => {
      const allAllowed = recipe.ingredients.every((ingredient) =>
        allowed.includes(ingredient)
      );

      const hasForbidden = recipe.ingredients.some((ingredient) =>
        forbidden.includes(ingredient)
      );

      return allAllowed && !hasForbidden;
    });
  }, [currentUser]);

  const getFeelingColor = (value) => {
    if (value === "טוב") return "#16a34a";
    if (value === "סביר") return "#d97706";
    if (value === "לא טוב") return "#dc2626";
    return "#6b7280";
  };

  const inputStyle = {
    width: "100%",
    padding: "14px",
    borderRadius: "14px",
    border: "1px solid #d1d5db",
    fontSize: "16px",
    boxSizing: "border-box",
    marginBottom: "12px",
    fontFamily: "Arial, sans-serif",
  };

  const cardStyle = {
    backgroundColor: "white",
    borderRadius: "20px",
    padding: "20px",
    boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
    marginBottom: "16px",
  };

  const mainButton = {
    padding: "14px 18px",
    borderRadius: "14px",
    border: "none",
    backgroundColor: "#10b981",
    color: "white",
    fontSize: "16px",
    fontWeight: "600",
    cursor: "pointer",
    width: "100%",
    marginTop: "16px",
  };

  const secondaryButton = {
    padding: "12px 18px",
    borderRadius: "14px",
    border: "1px solid #d1d5db",
    backgroundColor: "white",
    color: "#111827",
    fontSize: "16px",
    cursor: "pointer",
    width: "100%",
    marginTop: "12px",
  };

  const tagStyle = (type = "allowed") => ({
    backgroundColor: type === "allowed" ? "#ecfdf5" : "#fef2f2",
    color: type === "allowed" ? "#166534" : "#991b1b",
    padding: "8px 12px",
    borderRadius: "999px",
    fontSize: "14px",
    border: type === "allowed" ? "1px solid #bbf7d0" : "1px solid #fecaca",
    display: "inline-flex",
    alignItems: "center",
    gap: "8px",
  });

  if (screen === "auth") {
    return (
      <div
        dir="rtl"
        style={{
          minHeight: "100vh",
          backgroundColor: "#f8fafc",
          fontFamily: "Arial, sans-serif",
          padding: "24px 16px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div style={{ maxWidth: "460px", width: "100%" }}>
          {authMode === "login" ? (
            <div style={cardStyle}>
              <h1 style={{ marginTop: 0, fontSize: "32px" }}>התחברות</h1>

              <input
                placeholder="שם משתמש"
                value={loginData.username}
                onChange={(e) =>
                  setLoginData({ ...loginData, username: e.target.value })
                }
                style={inputStyle}
              />

              <input
                type="password"
                placeholder="סיסמה"
                value={loginData.password}
                onChange={(e) =>
                  setLoginData({ ...loginData, password: e.target.value })
                }
                style={inputStyle}
              />

              {authError && (
                <div
                  style={{
                    marginBottom: "12px",
                    color: "#dc2626",
                    backgroundColor: "#fef2f2",
                    padding: "10px",
                    borderRadius: "12px",
                    fontSize: "14px",
                  }}
                >
                  {authError}
                </div>
              )}

              <button style={mainButton} onClick={loginUser}>
                התחבר
              </button>

              <button
                style={secondaryButton}
                onClick={() => {
                  setAuthMode("register");
                  setAuthError("");
                }}
              >
                אין לי משתמש עדיין
              </button>
            </div>
          ) : (
            <div style={cardStyle}>
              <h1 style={{ marginTop: 0, fontSize: "32px" }}>הרשמה</h1>

              <input
                placeholder="שם מלא"
                value={registerData.fullName}
                onChange={(e) =>
                  setRegisterData({ ...registerData, fullName: e.target.value })
                }
                style={inputStyle}
              />

              <input
                placeholder="גיל"
                value={registerData.age}
                onChange={(e) =>
                  setRegisterData({ ...registerData, age: e.target.value })
                }
                style={inputStyle}
              />

              <input
                placeholder="שם משתמש"
                value={registerData.username}
                onChange={(e) =>
                  setRegisterData({ ...registerData, username: e.target.value })
                }
                style={inputStyle}
              />

              <input
                type="password"
                placeholder="סיסמה"
                value={registerData.password}
                onChange={(e) =>
                  setRegisterData({ ...registerData, password: e.target.value })
                }
                style={inputStyle}
              />

              <select
                value={registerData.diseaseType}
                onChange={(e) =>
                  setRegisterData({
                    ...registerData,
                    diseaseType: e.target.value,
                  })
                }
                style={inputStyle}
              >
                <option>קרוהן</option>
                <option>קוליטיס</option>
              </select>

              <select
                value={registerData.currentStatus}
                onChange={(e) =>
                  setRegisterData({
                    ...registerData,
                    currentStatus: e.target.value,
                  })
                }
                style={inputStyle}
              >
                <option>רמיסיה</option>
                <option>רגיש</option>
                <option>התלקחות</option>
              </select>

              <div style={{ marginBottom: "12px", fontWeight: "600" }}>
                העלאת PDF מהתזונאית
              </div>

              <input
                type="file"
                accept="application/pdf"
                onChange={(e) => {
                  const file = e.target.files[0];
                  if (file) handlePdfUpload(file);
                }}
                style={{ marginBottom: "10px" }}
              />

              {registerData.nutritionFileName && (
                <div style={{ fontSize: "14px", color: "#4b5563" }}>
                  קובץ שנבחר: {registerData.nutritionFileName}
                </div>
              )}

              {pdfLoading && (
                <div style={{ marginTop: "10px", color: "#2563eb" }}>
                  קורא PDF...
                </div>
              )}

              {pdfMessage && (
                <div
                  style={{
                    marginTop: "12px",
                    color: "#374151",
                    backgroundColor: "#f3f4f6",
                    padding: "10px",
                    borderRadius: "12px",
                    fontSize: "14px",
                  }}
                >
                  {pdfMessage}
                </div>
              )}

              <button
                style={secondaryButton}
                onClick={() => {
                  setAuthMode("login");
                  setAuthError("");
                }}
              >
                כבר יש לי משתמש
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (screen === "reviewFoods") {
    return (
      <div
        dir="rtl"
        style={{
          minHeight: "100vh",
          backgroundColor: "#f8fafc",
          fontFamily: "Arial, sans-serif",
          padding: "24px 16px",
        }}
      >
        <div style={{ maxWidth: "460px", margin: "0 auto" }}>
          <div style={cardStyle}>
            <h1 style={{ marginTop: 0, fontSize: "30px" }}>
              אישור מאכלים מה־PDF
            </h1>
            <p style={{ color: "#6b7280" }}>
              הסריקה מציגה רק מאכלים שנמצאו בשורות של מותר/מומלץ או אסור/להימנע.
              עכשיו תתקן מה שצריך.
            </p>
          </div>

          <div style={cardStyle}>
            <h3 style={{ marginTop: 0 }}>מאכלים מותרים</h3>

            {candidateAllowed.length === 0 ? (
              <p style={{ color: "#6b7280" }}>לא זוהו מאכלים מותרים.</p>
            ) : (
              <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                {candidateAllowed.map((food) => (
                  <span key={food} style={tagStyle("allowed")}>
                    {food}
                    <button
                      onClick={() => removeAllowed(food)}
                      style={{
                        border: "none",
                        background: "transparent",
                        cursor: "pointer",
                        color: "#166534",
                        fontWeight: "700",
                      }}
                    >
                      ✕
                    </button>
                  </span>
                ))}
              </div>
            )}

            <div style={{ marginTop: "14px" }}>
              <input
                placeholder="הוסף מאכל מותר ידנית"
                value={manualAllowed}
                onChange={(e) => setManualAllowed(e.target.value)}
                style={inputStyle}
              />
              <button style={secondaryButton} onClick={addManualAllowed}>
                הוסף למותרים
              </button>
            </div>
          </div>

          <div style={cardStyle}>
            <h3 style={{ marginTop: 0 }}>מאכלים אסורים</h3>

            {candidateForbidden.length === 0 ? (
              <p style={{ color: "#6b7280" }}>לא זוהו מאכלים אסורים.</p>
            ) : (
              <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                {candidateForbidden.map((food) => (
                  <span key={food} style={tagStyle("forbidden")}>
                    {food}
                    <button
                      onClick={() => removeForbidden(food)}
                      style={{
                        border: "none",
                        background: "transparent",
                        cursor: "pointer",
                        color: "#991b1b",
                        fontWeight: "700",
                      }}
                    >
                      ✕
                    </button>
                  </span>
                ))}
              </div>
            )}

            <div style={{ marginTop: "14px" }}>
              <input
                placeholder="הוסף מאכל אסור ידנית"
                value={manualForbidden}
                onChange={(e) => setManualForbidden(e.target.value)}
                style={inputStyle}
              />
              <button style={secondaryButton} onClick={addManualForbidden}>
                הוסף לאסורים
              </button>
            </div>
          </div>

          <div style={cardStyle}>
            <button style={mainButton} onClick={registerUser}>
              שמור והמשך
            </button>
            <button
              style={secondaryButton}
              onClick={() => setScreen("auth")}
            >
              חזור
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div
      dir="rtl"
      style={{
        minHeight: "100vh",
        backgroundColor: "#f8fafc",
        fontFamily: "Arial, sans-serif",
        padding: "24px 16px",
      }}
    >
      <div style={{ maxWidth: "460px", margin: "0 auto" }}>
        {screen === "home" && currentUser && (
          <>
            <div
              style={{
                background: "linear-gradient(135deg, #10b981, #34d399)",
                color: "white",
                borderRadius: "24px",
                padding: "24px",
                boxShadow: "0 10px 30px rgba(16,185,129,0.18)",
                marginBottom: "18px",
              }}
            >
              <div style={{ fontSize: "14px", opacity: 0.95, marginBottom: "8px" }}>
                שלום {currentUser.fullName}
              </div>
              <h1 style={{ margin: 0, fontSize: "32px", lineHeight: "1.2" }}>
                מה בטוח לי לאכול היום?
              </h1>
              <div style={{ marginTop: "12px", fontSize: "15px" }}>
                מצב נוכחי: <strong>{currentUser.currentStatus}</strong>
              </div>
            </div>

            <div style={cardStyle}>
              <h3 style={{ marginTop: 0 }}>מאכלים מותרים</h3>
              {currentUser.allowedFoods?.length ? (
                <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                  {currentUser.allowedFoods.map((food) => (
                    <span key={food} style={tagStyle("allowed")}>
                      {food}
                    </span>
                  ))}
                </div>
              ) : (
                <p style={{ color: "#6b7280" }}>אין מאכלים מותרים.</p>
              )}
            </div>

            <div style={cardStyle}>
              <h3 style={{ marginTop: 0 }}>מאכלים אסורים</h3>
              {currentUser.forbiddenFoods?.length ? (
                <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                  {currentUser.forbiddenFoods.map((food) => (
                    <span key={food} style={tagStyle("forbidden")}>
                      {food}
                    </span>
                  ))}
                </div>
              ) : (
                <p style={{ color: "#6b7280" }}>אין מאכלים אסורים.</p>
              )}
            </div>

            <div style={cardStyle}>
              <h3 style={{ marginTop: 0 }}>מתכונים לפי המאכלים המותרים</h3>
              {suggestedRecipes.length ? (
                <div style={{ display: "grid", gap: "12px" }}>
                  {suggestedRecipes.map((recipe) => (
                    <div
                      key={recipe.name}
                      style={{
                        backgroundColor: "#f0fdf4",
                        border: "1px solid #bbf7d0",
                        borderRadius: "16px",
                        padding: "14px",
                      }}
                    >
                      <div
                        style={{
                          fontSize: "17px",
                          fontWeight: "700",
                          marginBottom: "8px",
                        }}
                      >
                        {recipe.name}
                      </div>
                      <div style={{ color: "#4b5563", fontSize: "14px" }}>
                        {recipe.description}
                      </div>
                      <div
                        style={{
                          color: "#166534",
                          fontSize: "14px",
                          marginTop: "8px",
                        }}
                      >
                        רכיבים: {recipe.ingredients.join(", ")}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p style={{ color: "#6b7280" }}>
                  עדיין אין מספיק מאכלים מותרים כדי לבנות מתכונים.
                </p>
              )}
            </div>

            <div style={cardStyle}>
              <h3 style={{ marginTop: 0 }}>מה אכלתי היום</h3>

              {meals.length === 0 ? (
                <p style={{ color: "#6b7280" }}>עדיין לא הוספת ארוחות.</p>
              ) : (
                <div style={{ display: "grid", gap: "10px" }}>
                  {meals.map((meal, index) => (
                    <div
                      key={`${meal.name}-${index}`}
                      style={{
                        border: "1px solid #e5e7eb",
                        borderRadius: "14px",
                        padding: "12px",
                        backgroundColor: "#f9fafb",
                      }}
                    >
                      <div style={{ fontWeight: "600" }}>{meal.name}</div>
                      <div
                        style={{
                          marginTop: "6px",
                          fontSize: "14px",
                          color: getFeelingColor(meal.feeling),
                        }}
                      >
                        הרגשתי אחרי זה: {meal.feeling}
                      </div>
                      <button
                        onClick={() => deleteMeal(index)}
                        style={{
                          marginTop: "10px",
                          backgroundColor: "#fee2e2",
                          color: "#dc2626",
                          border: "none",
                          padding: "8px 12px",
                          borderRadius: "10px",
                          cursor: "pointer",
                          fontSize: "14px",
                        }}
                      >
                        מחק
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <button style={mainButton} onClick={() => setScreen("addMeal")}>
                הוספת ארוחה
              </button>
            </div>

            <button style={secondaryButton} onClick={() => setScreen("profile")}>
              עריכת פרופיל
            </button>

            <button style={secondaryButton} onClick={logoutUser}>
              התנתק
            </button>
          </>
        )}

        {screen === "addMeal" && (
          <div style={cardStyle}>
            <h1 style={{ marginTop: 0, fontSize: "30px" }}>הוספת ארוחה</h1>

            <input
              placeholder="מה אכלת?"
              value={mealInput}
              onChange={(e) => setMealInput(e.target.value)}
              style={inputStyle}
            />

            <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
              {["טוב", "סביר", "לא טוב"].map((item) => (
                <button
                  key={item}
                  onClick={() => setMealFeeling(item)}
                  style={{
                    padding: "12px 18px",
                    borderRadius: "12px",
                    border:
                      mealFeeling === item
                        ? "2px solid #10b981"
                        : "1px solid #d1d5db",
                    backgroundColor:
                      mealFeeling === item ? "#ecfdf5" : "white",
                    cursor: "pointer",
                  }}
                >
                  {item}
                </button>
              ))}
            </div>

            <button style={mainButton} onClick={saveMeal}>
              שמור ארוחה
            </button>

            <button style={secondaryButton} onClick={() => setScreen("home")}>
              חזור
            </button>
          </div>
        )}

        {screen === "profile" && currentUser && (
          <div style={cardStyle}>
            <h1 style={{ marginTop: 0, fontSize: "30px" }}>עריכת פרופיל</h1>

            <input
              placeholder="שם מלא"
              value={currentUser.fullName}
              onChange={(e) =>
                updateCurrentUserField("fullName", e.target.value)
              }
              style={inputStyle}
            />

            <input
              placeholder="גיל"
              value={currentUser.age}
              onChange={(e) => updateCurrentUserField("age", e.target.value)}
              style={inputStyle}
            />

            <select
              value={currentUser.currentStatus}
              onChange={(e) =>
                updateCurrentUserField("currentStatus", e.target.value)
              }
              style={inputStyle}
            >
              <option>רמיסיה</option>
              <option>רגיש</option>
              <option>התלקחות</option>
            </select>

            <button style={mainButton} onClick={saveProfileChanges}>
              שמור שינויים
            </button>

            <button style={secondaryButton} onClick={() => setScreen("home")}>
              חזור
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
